const input = $input.first().json.body.combatPlan.targetInfo;

function parseLocation(input) {
    // Check if input is already a structured object
    if (typeof input === 'object' && input !== null) {

        // Handle nested coordinates: { targetCoordinates: { x, y, z }, ... }
        if (input.targetCoordinates && 
            typeof input.targetCoordinates.x === 'number' && 
            typeof input.targetCoordinates.y === 'number' && 
            typeof input.targetCoordinates.z === 'number') {
            return {
                type: 'coordinates',
                x: input.targetCoordinates.x,
                y: input.targetCoordinates.y,
                z: input.targetCoordinates.z,
                targetType: input.targetType || input.primaryTarget,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle flat coordinates: { x, y, z }
        if (typeof input.x === 'number' && 
            typeof input.y === 'number' && 
            typeof input.z === 'number') {
            return {
                type: 'coordinates',
                x: input.x,
                y: input.y,
                z: input.z
            };
        }

        // Handle player object: { type: 'player', name: '...' }
        if (input.type === 'player' && input.name) {
            return {
                type: 'player',
                name: input.name
            };
        }

        // Handle player object: { targetType: 'player', primaryTarget: '...' }
        if (input.targetType === 'player' && input.primaryTarget) {
            return {
                type: 'player',
                name: input.primaryTarget,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle landmark object: { name: '...' }
        if (input.name && !input.type) {
            return {
                type: 'landmark',
                name: input.name
            };
        }
    }

    // If input is a string, parse it as before
    if (typeof input === 'string') {
        const coordMatch = input.match(/^(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)$/);
        if (coordMatch) {
            return {
                type: 'coordinates',
                x: parseFloat(coordMatch[1]),
                y: parseFloat(coordMatch[2]),
                z: parseFloat(coordMatch[3])
            };
        }

        const playerMatch = input.match(/(?:next\s+to\s+)?player\s+(\w+)/i);
        if (playerMatch) {
            return {
                type: 'player',
                name: playerMatch[1]
            };
        }

        return {
            type: 'landmark',
            name: input.trim()
        };
    }

    // Fallback for unexpected types
    return {
        type: 'unknown',
        raw: input
    };
}

const location = parseLocation(input);
return { location };

const status = $input.item.json.location || $input.item.json.position;
return {
  Position: {
    x: Math.floor(status?.x || 0),
    y: Math.floor(status?.y || -60),
    z: Math.floor(status?.z || 0)
  }
}

const targetLocation = $('Teleport Workers').first().json.buildLocation;
const tasks = $input.first().json;
const targetInfo = $('Webhook').first().json.body.targetInfo || {};
const sessionId = $('Webhook').first().json.body.sessionId || 'combat_session';
const COMBAT_RADIUS = 20;
const OFFSET_DISTANCE = 5;
const MIN_TEAMMATE_SPACING = 3;

const rallyPoint = {
  x: Math.floor(targetLocation.x),
  y: Math.floor(targetLocation.y),
  z: Math.floor(targetLocation.z)
};

const getCardinalDirection = (angleRadians) => {
  const normalized = ((angleRadians % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  if (normalized < Math.PI / 4 || normalized >= 7 * Math.PI / 4) return 'east';
  if (normalized < 3 * Math.PI / 4) return 'north';
  if (normalized < 5 * Math.PI / 4) return 'west';
  return 'south';
};

const soldierNames = Object.keys(tasks).sort((a, b) => {
  const numA = parseInt(a.match(/\d+/)?.[0] || 0);
  const numB = parseInt(b.match(/\d+/)?.[0] || 0);
  return numA - numB;
});

const numSoldiers = soldierNames.length;
const updatedTasks = {};

soldierNames.forEach((soldierName, index) => {
  const angleRadians = (index / numSoldiers) * 2 * Math.PI;

  const startX = Math.floor(rallyPoint.x + Math.cos(angleRadians) * OFFSET_DISTANCE);
  const startZ = Math.floor(rallyPoint.z + Math.sin(angleRadians) * OFFSET_DISTANCE);
  const startY = rallyPoint.y;

  const cardinalDirection = getCardinalDirection(angleRadians);
  const otherSoldiers = soldierNames.filter(s => s !== soldierName);

  let task = tasks[soldierName];

  // Update TARGET field
  task = task.replace(
    /TARGET: undefined/,
    `TARGET: Iron Golem`
  );

  // Update POSITION
  const newPosition = `You start ${OFFSET_DISTANCE} blocks ${cardinalDirection} of the target at coordinates (${startX}, ${startY}, ${startZ}).`;
  task = task.replace(
    /POSITION:[\s\S]*?(?=\n\nEQUIPMENT:|EQUIPMENT:)/,
    `POSITION: ${newPosition}\n\n`
  );

  // Add combat zone info
  const combatZoneInfo = `
COMBAT ZONE:
- Your Start Position: (${startX}, ${startY}, ${startZ})
- Rally Point: (${rallyPoint.x}, ${rallyPoint.y}, ${rallyPoint.z})
- Max Chase Distance: ${COMBAT_RADIUS} blocks from rally point
- Your Approach: ${cardinalDirection} side

TEAMMATES: ${otherSoldiers.join(', ') || 'None'}
- Keep ${MIN_TEAMMATE_SPACING}+ blocks from teammates
- Stay on YOUR side of target`;

  if (task.includes('REMINDERS:')) {
    task = task.replace('REMINDERS:', `${combatZoneInfo}\n\nREMINDERS:`);
  } else {
    task += '\n' + combatZoneInfo;
  }

  updatedTasks[soldierName] = task;
});

return {
  tasks: updatedTasks,
  combatMetadata: {
    sessionId: sessionId,
    rallyPoint: rallyPoint,
    combatRadius: COMBAT_RADIUS,
    soldierCount: numSoldiers
  }
};

// Code Node: Generate Combat Tasks (DYNAMIC - Works for any target)

const taskDivision = $('Webhook').first().json.body.combatPlan.taskDivision;
const buildRequest = $('Webhook').first().json.body.combatPlan.combatRequest;
const location = $('Webhook').first().json.body.location || "the target area";
const targetInfo = $('Webhook').first().json.body.combatPlan.targetInfo;
const codePattern = $('Webhook').first().json.body.combatPlan.codePattern || {};

// DYNAMIC: Get target from webhook
const targetName = targetInfo.primaryTarget || "hostile mob";
const searchRange = targetInfo.searchRange || 50;
const meleeRange = targetInfo.meleeRange || 3.5;
const targetType = targetInfo.targetType || "mob"; // "mob", "player", "entity"

let coordinatedTasks = {};

Object.entries(taskDivision).forEach(([soldierRole, task]) => {

  // Format equipment info
  const equipment = task.equipment || {};
  const equipmentStr = [
    equipment.weapon ? `Weapon: ${equipment.weapon}` : null,
    equipment.armor ? `Armor: ${equipment.armor}` : null
  ].filter(Boolean).join(', ') || 'Use whatever is in inventory';

  // Format constraints
  const constraintsStr = (task.constraints || [])
    .map(c => `- ${c}`)
    .join('\n');

  // Build target search logic (generic for any entity name)
  let targetSearchCode = '';
  if (targetType === 'player') {
    // Search for players
    targetSearchCode = `let target = Object.values(bot.players).find(p => 
  p && p.entity && 
  p.entity.position.distanceTo(bot.entity.position) < ${searchRange}
);`;
  } else {
    // Search for mobs/entities by name (case insensitive, word matching)
    const targetWords = targetName.toLowerCase().split('_').join(' ').split(' ');
    const searchLogic = targetWords.map(word => `e.name.toLowerCase().includes('${word}')`).join(' && ');

    targetSearchCode = `let target = Object.values(bot.entities).find(e => 
  e.name && 
  ${searchLogic} &&
  e.position.distanceTo(bot.entity.position) < ${searchRange}
);`;
  }

  // Build attack code template with delay for Soldier2
  let attackCode = `const MELEE_RANGE = ${meleeRange};
const maxCombatTime = 60000;
const startTime = Date.now();

console.log('[${soldierRole}] === COMBAT START ===');
console.log('[${soldierRole}] Position:', bot.entity.position);`;

  // Add 1.5 second delay ONLY for Soldier2
  if (soldierRole === 'Soldier2') {
    attackCode += `

// Flanker: Wait for tank to engage first
console.log('[${soldierRole}] Waiting 1.5 seconds for primary engagement...');
await skills.wait(bot, 1500);`;
  }

  attackCode += `

const weapon = bot.inventory.items().find(i => i.name.includes('sword')) || bot.inventory.items().find(i => i.name.includes('axe')) || null;
console.log('[${soldierRole}] Weapon:', weapon ? weapon.name : 'NONE (fists)');
if (weapon) await bot.equip(weapon, 'hand');

const allEntities = Object.values(bot.entities).filter(e => e.name);
console.log('[${soldierRole}] All entities:', allEntities.slice(0, 10).map(e => e.name + ' (' + Math.floor(e.position.distanceTo(bot.entity.position)) + 'm)').join(', '));

// Search for target: ${targetName}
${targetSearchCode}

console.log('[${soldierRole}] Target ${targetName}:', target ? 'FOUND at ' + Math.floor(target.position.distanceTo(bot.entity.position)) + 'm' : 'NOT FOUND');

if (target) {
  console.log('[${soldierRole}] Starting attack');
  let hits = 0;

  while (target && target.isValid && (Date.now() - startTime) < maxCombatTime) {
    if (bot.health < 12) {
      console.log('[${soldierRole}] Low health (' + bot.health + '/20), retreating');
      await skills.moveAway(bot, 10);
      break;
    }

    const distance = target.position.distanceTo(bot.entity.position);

    if (distance <= MELEE_RANGE) {
      await bot.lookAt(target.position);
      await bot.attack(target);
      hits++;
      if (hits % 3 === 0) console.log('[${soldierRole}] Hits: ' + hits + ', Health: ' + bot.health);
    } else {
      // Move closer to target
      await bot.lookAt(target.position);
      bot.setControlState('forward', true);
    }

    await skills.wait(bot, 300);
    target = target && target.isValid ? target : null;
  }

  console.log('[${soldierRole}] Combat done - Total hits: ' + hits + ', Final health: ' + bot.health);
  if ((Date.now() - startTime) >= maxCombatTime) {
    console.log('[${soldierRole}] Combat timeout (60 seconds) reached');
  }
} else {
  console.log('[${soldierRole}] ERROR: No ${targetName} found within ${searchRange} blocks!');
}

console.log('[${soldierRole}] Holding position');
bot.setControlState('forward', false);`;

  coordinatedTasks[soldierRole] = `COMBAT MISSION: ${buildRequest}

Location: Near ${location}
Role: ${soldierRole}
Combat Role: ${(task.combatRole || 'soldier').toUpperCase()}

OBJECTIVE: ${task.objective}

TARGET: ${targetName}

EQUIPMENT: ${equipmentStr}

TACTICS:
1. Use the provided attack code template exactly as written
